import itertools

def count_good_paths(board):
    n = len(board)
    h = [[0]*n for _ in range(n)]

    # Values in decreasing order
    values = []
    for r in range(n):
        for c in range(n):
            values.append((board[r][c], r, c))
    values.sort(key=lambda x: x[0], reverse=True)

    for val, r, c in values:
        count = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if board[nr][nc] > val:
                    count += h[nr][nc]
        h[r][c] = count

    total_good_paths = 0
    for r in range(n):
        for c in range(n):
            is_local_min = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    if board[nr][nc] < board[r][c]:
                        is_local_min = False
                        break
            if is_local_min:
                total_good_paths += h[r][c]
    return total_good_paths

def solve_small_n(n):
    min_paths = float('inf')
    for p in itertools.permutations(range(1, n*n + 1)):
        board = [p[i:i+n] for i in range(0, n*n, n)]
        min_paths = min(min_paths, count_good_paths(board))
    return min_paths

